using System;
using System.Collections.Generic;
using Framework.AI.Actions;
using Framework.AI.Core;
using Game.AI.Actions;
using Game.AI.Decision;
using Game.AI.Parameters;
using Game.AI.Perception;
using Game.AI.Spatial;
using Game.AI.Tactics;
using UnityEngine;

namespace Game.AI.Core
{
    /// <summary>
    /// 認識、評価、行動選択を統合した自律型敵AI。
    /// </summary>
    /// <remarks>
    /// AIの思考更新を担当する。
    /// 実際のフレーム単位の移動更新は外部で行う。
    /// 敵AIコンテキストとパラメーターの所有権は持たない。
    /// </remarks>
    public sealed class MazeEnemyAgent
        : AgentBase<MazeEnemyParameter>
    {
        /// <summary>
        /// 認識対象の情報を取得する処理。
        /// </summary>
        private readonly Func<
            IReadOnlyList<MazeEnemyTargetSnapshot>>
            targetProvider;

        /// <summary>
        /// 敵AIの基本コンテキスト。
        /// </summary>
        public MazeEnemyContext EnemyContext { get; }

        /// <summary>
        /// 対象の認識システム。
        /// </summary>
        public MazeEnemyPerceptionController Perception
        {
            get;
            private set;
        }

        /// <summary>
        /// 縄張り評価システム。
        /// </summary>
        public MazeEnemyTerritory Territory
        {
            get;
            private set;
        }

        /// <summary>
        /// 空間評価システム。
        /// </summary>
        public MazeEnemySpatialEvaluator SpatialEvaluator
        {
            get;
            private set;
        }

        /// <summary>
        /// 戦術評価システム。
        /// </summary>
        public MazeEnemyTacticalEvaluator TacticalEvaluator
        {
            get;
            private set;
        }

        /// <summary>
        /// 行動評価システム。
        /// </summary>
        public MazeEnemyUtility Utility
        {
            get;
            private set;
        }

        /// <summary>
        /// 行動実行用コンテキスト。
        /// </summary>
        public MazeEnemyActionContext ActionContext
        {
            get;
            private set;
        }

        /// <summary>
        /// 行動管理システム。
        /// </summary>
        public AgentActionController<
            MazeEnemyActionType,
            MazeEnemyActionContext> ActionController
        {
            get;
            private set;
        }

        /// <summary>
        /// 最後に選択した行動候補。
        /// </summary>
        public MazeEnemyUtilityCandidate LastSelectedCandidate
        {
            get;
            private set;
        }

        /// <summary>
        /// 現在実行している行動。
        /// </summary>
        public MazeEnemyActionType CurrentAction
        {
            get
            {
                if (ActionController != null &&
                    ActionController.TryGetCurrentActionId(
                        out var action))
                {
                    return action;
                }

                return MazeEnemyActionType.None;
            }
        }

        /// <summary>
        /// 現在行動を実行しているか。
        /// </summary>
        public bool HasCurrentAction =>
            ActionController != null &&
            ActionController.HasCurrentAction;

        /// <summary>
        /// AIの思考処理が実行可能であるか。
        /// </summary>
        public bool CanThink =>
            IsActive &&
            EnemyContext.IsValid &&
            EnemyContext.CanAct &&
            Utility != null &&
            Utility.IsValid;

        /// <summary>
        /// 敵AIを生成する。
        /// </summary>
        /// <param name="enemyContext">敵AIコンテキスト</param>
        /// <param name="targetProvider">
        /// 現在の認識対象候補を取得する処理
        /// </param>
        public MazeEnemyAgent(
            MazeEnemyContext enemyContext,
            Func<IReadOnlyList<MazeEnemyTargetSnapshot>>
                targetProvider)
        {
            EnemyContext = enemyContext ??
                throw new ArgumentNullException(
                    nameof(enemyContext));

            this.targetProvider = targetProvider ??
                throw new ArgumentNullException(
                    nameof(targetProvider));

            if (!enemyContext.IsValid)
            {
                throw new ArgumentException(
                    "敵AIコンテキストが無効です。",
                    nameof(enemyContext));
            }
        }

        /// <summary>
        /// 現在の行動目的地を取得する。
        /// </summary>
        /// <param name="destination">現在の目的地</param>
        /// <returns>取得できた場合はtrue</returns>
        public bool TryGetCurrentDestination(
            out Vector2Int destination)
        {
            destination = default;

            return ActionContext != null &&
                ActionContext.TryGetDestination(
                    CurrentAction,
                    out destination);
        }

        /// <summary>
        /// 敵AIの各システムを初期化する。
        /// </summary>
        protected override void OnInitialize()
        {
            if (!ReferenceEquals(
                    Context,
                    EnemyContext.Agent))
            {
                throw new InvalidOperationException(
                    "AgentContextが一致していません。");
            }

            try
            {
                Perception =
                    new MazeEnemyPerceptionController(
                        EnemyContext);

                Territory =
                    new MazeEnemyTerritory(
                        EnemyContext);

                SpatialEvaluator =
                    new MazeEnemySpatialEvaluator(
                        EnemyContext,
                        Territory);

                TacticalEvaluator =
                    new MazeEnemyTacticalEvaluator(
                        EnemyContext);

                ActionContext =
                    new MazeEnemyActionContext(
                        EnemyContext);

                Utility =
                    new MazeEnemyUtility(
                        EnemyContext,
                        ActionContext,
                        Perception,
                        Territory,
                        SpatialEvaluator,
                        TacticalEvaluator);

                ActionController =
                    new AgentActionController<
                        MazeEnemyActionType,
                        MazeEnemyActionContext>();

                RegisterActions();

                ActionController.ActionEnded +=
                    HandleActionEnded;
            }
            catch
            {
                ReleaseSystems();

                throw;
            }
        }

        /// <summary>
        /// 敵AIが実行可能な行動を登録する。
        /// </summary>
        private void RegisterActions()
        {
            ActionController.TryRegister(
                new MazeEnemyIdleAction());

            RegisterMoveAction(
                MazeEnemyActionType.Patrol,
                0.4f,
                0.1f);

            RegisterMoveAction(
                MazeEnemyActionType.Explore,
                0.4f,
                0.1f);

            RegisterMoveAction(
                MazeEnemyActionType.Chase,
                0.2f,
                0f);

            RegisterMoveAction(
                MazeEnemyActionType.Intercept,
                0.2f,
                0.1f);

            RegisterMoveAction(
                MazeEnemyActionType.Escape,
                0.2f,
                0f);

            RegisterMoveAction(
                MazeEnemyActionType.ReturnToTerritory,
                0.4f,
                0.1f);
        }

        /// <summary>
        /// 指定された移動行動を登録する。
        /// </summary>
        /// <param name="action">行動の種類</param>
        /// <param name="minimumDuration">最短継続時間</param>
        /// <param name="cooldown">再実行待機時間</param>
        private void RegisterMoveAction(
            MazeEnemyActionType action,
            float minimumDuration,
            float cooldown)
        {
            var settings =
                new AgentActionSettings(
                    minimumDuration,
                    cooldown,
                    canInterrupt: true);

            ActionController.TryRegister(
                new MazeEnemyMoveAction(
                    action,
                    settings));
        }

        /// <summary>
        /// 敵AIを有効化する。
        /// </summary>
        protected override void OnActivated()
        {
            ActionController.SetPaused(false);

            EnemyContext.Movement.Resume();
        }

        /// <summary>
        /// 敵AIの思考と行動を更新する。
        /// </summary>
        /// <param name="deltaTime">AI更新の経過時間</param>
        protected override void OnTick(float deltaTime)
        {
            if (!CanThink)
            {
                return;
            }

            // 認識対象候補を取得する。
            // 対象候補の情報を直接戦術判断には使用しない。
            IReadOnlyList<MazeEnemyTargetSnapshot> targets =
                targetProvider() ??
                Array.Empty<MazeEnemyTargetSnapshot>();

            if (!Perception.UpdatePerception(targets))
            {
                return;
            }

            // ForgetReachedMemory();

            // 現在の行動を終了または継続できるか更新する。
            ActionController.Tick(
                ActionContext,
                deltaTime);

            MazeEnemyActionType currentAction =
                CurrentAction;

            if (!Utility.Evaluate(currentAction))
            {
                return;
            }

            // 現在の行動の目的地を最新の評価結果へ更新する。
            SynchronizeCurrentDestination(currentAction);

            if (!Utility.TrySelect(
                    currentAction,
                    out var candidate))
            {
                return;
            }

            LastSelectedCandidate = candidate;

            TryExecuteCandidate(candidate);
        }

        /// <summary>
        /// 到着済みの記憶座標を認識情報から削除する。
        /// </summary>
        /// <remarks>
        /// 最後に対象を見た場所へ到着しても
        /// 対象が見つからない場合に探索を再開させる。
        /// </remarks>
        // private void ForgetReachedMemory()
        // {
        //     if (!EnemyContext.IsAtCellCenter)
        //     {
        //         return;
        //     }

        //     if (!Perception.TryGetBestObservation(
        //             MazeEnemyTargetType.Player,
        //             out var target))
        //     {
        //         return;
        //     }

        //     if (target.IsRemembered &&
        //         target.LastKnownPosition ==
        //             EnemyContext.CurrentCell)
        //     {
        //         Perception.Forget(target.Id);
        //     }
        // }

        /// <summary>
        /// 現在の行動の目的地を同期する。
        /// </summary>
        /// <param name="currentAction">現在の行動</param>
        private void SynchronizeCurrentDestination(
            MazeEnemyActionType currentAction)
        {
            if (!MazeEnemyActionContext.IsMovementAction(
                    currentAction))
            {
                return;
            }

            if (Utility.TryGetCandidate(
                    currentAction,
                    out var candidate) &&
                candidate.HasDestination)
            {
                ActionContext.TrySetDestination(
                    currentAction,
                    candidate.Destination);

                return;
            }

            // 認識消失などで行動候補が無効になった場合は
            // 古い目的地を破棄して行動を終了する。
            ActionController.Stop(ActionContext);

            ActionContext.RemoveDestination(
                currentAction);
        }

        /// <summary>
        /// 選択された行動候補を実行する。
        /// </summary>
        /// <param name="candidate">行動候補</param>
        /// <returns>実行可能な場合はtrue</returns>
        private bool TryExecuteCandidate(
            MazeEnemyUtilityCandidate candidate)
        {
            if (!candidate.IsValid)
            {
                return false;
            }

            if (candidate.Action == CurrentAction)
            {
                // 同じ行動は再開始しない。
                return true;
            }

            if (ActionController.IsOnCooldown(
                    candidate.Action))
            {
                return false;
            }

            if (candidate.HasDestination &&
                !ActionContext.TrySetDestination(
                    candidate.Action,
                    candidate.Destination))
            {
                return false;
            }

            // 脅威からの逃走は通常の継続時間制限を解除する。
            bool forceInterrupt =
                candidate.Action ==
                    MazeEnemyActionType.Escape;

            bool started =
                ActionController.TryStartAction(
                    candidate.Action,
                    ActionContext,
                    forceInterrupt);

            if (!started &&
                candidate.Action != CurrentAction)
            {
                ActionContext.RemoveDestination(
                    candidate.Action);
            }

            return started;
        }

        /// <summary>
        /// 行動終了時に不要な目的地を削除する。
        /// </summary>
        /// <param name="action">終了した行動</param>
        /// <param name="reason">行動の終了理由</param>
        private void HandleActionEnded(
            MazeEnemyActionType action,
            AgentActionExitReason reason)
        {
            ActionContext.RemoveDestination(action);
        }

        /// <summary>
        /// 敵AIの思考と移動を一時停止する。
        /// </summary>
        protected override void OnPaused()
        {
            ActionController.SetPaused(true);

            EnemyContext.Movement.Pause();
        }

        /// <summary>
        /// 敵AIの思考と移動を再開する。
        /// </summary>
        protected override void OnResumed()
        {
            ActionController.SetPaused(false);

            EnemyContext.Movement.Resume();
        }

        /// <summary>
        /// 敵AIを無効化する。
        /// </summary>
        protected override void OnDeactivated()
        {
            ActionController.Stop(ActionContext);

            ActionContext.ClearDestinations();

            Utility.Clear();

            LastSelectedCandidate = default;

            // 無効化時は現在のセル中心へ戻して停止する。
            EnemyContext.Movement.StopImmediately();
            EnemyContext.Movement.Pause();
        }

        /// <summary>
        /// 敵AIが所有するシステムを解放する。
        /// </summary>
        private void ReleaseSystems()
        {
            if (ActionController != null)
            {
                ActionController.ActionEnded -=
                    HandleActionEnded;

                if (ActionContext != null &&
                    !ActionContext.IsDisposed)
                {
                    ActionController.Stop(ActionContext);
                }
            }

            ActionController = null;

            Utility?.Clear();
            Utility = null;

            ActionContext?.Dispose();
            ActionContext = null;

            TacticalEvaluator?.Dispose();
            TacticalEvaluator = null;

            SpatialEvaluator?.Dispose();
            SpatialEvaluator = null;

            Territory?.Dispose();
            Territory = null;

            Perception?.Dispose();
            Perception = null;

            LastSelectedCandidate = default;
        }

        /// <summary>
        /// 敵AIを破棄する。
        /// </summary>
        protected override void OnDispose()
        {
            ReleaseSystems();

            if (EnemyContext.IsValid)
            {
                EnemyContext.Movement.StopImmediately();
                EnemyContext.Movement.Pause();
            }
        }
    }
}
